package com.arqly.backend.notification;
import com.arqly.backend.repository.*;import java.time.LocalDate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;
@Component public class NotificationReminderScheduler {private final TenantRepository tenants;private final ProjectStageRepository stages;private final ConstructionDiaryEntryRepository diary;private final com.arqly.backend.repository.FinancialInstallmentRepository financial;private final NotificationDomainPublisher publisher;public NotificationReminderScheduler(TenantRepository tenants,ProjectStageRepository stages,ConstructionDiaryEntryRepository diary,com.arqly.backend.repository.FinancialInstallmentRepository financial,NotificationDomainPublisher publisher){this.tenants=tenants;this.stages=stages;this.diary=diary;this.financial=financial;this.publisher=publisher;}@Scheduled(cron="0 0 8 * * *") public void run(){var today=LocalDate.now();tenants.findAll().forEach(t->{stages.findDueForCalendar(t.getId(),today.plusDays(2),today.plusDays(2)).forEach(publisher::reminder);diary.findAllByTenantIdAndDeletedFalseAndNextVisitDateBetween(t.getId(),today.plusDays(1),today.plusDays(1)).forEach(publisher::visitReminder);financial.findAllByEntryTenantIdAndEntryDeletedFalse(t.getId()).stream().filter(i->i.getStatus()!=com.arqly.backend.entity.FinancialInstallmentStatus.PAID&&i.getStatus()!=com.arqly.backend.entity.FinancialInstallmentStatus.CANCELLED&&i.getDueDate().equals(today.plusDays(2))).forEach(publisher::financialReminder);});}}
